static struct PyModuleDef module_def = {PyModuleDef_HEAD_INIT, "_cfjs", NULL, -1, methods};

static PyObject *init_cfjs(void) {
  if (PyType_Ready(&JsRefType) < 0) return NULL;
  PyObject *m = PyModule_Create(&module_def);
  if (m && PyModule_AddObjectRef(m, "JsRef", (PyObject *)&JsRefType) < 0) Py_CLEAR(m);
  return m;
}

// Before Py_Initialize, which runs at pre-initialization; the constructor
// runs from _initialize, which wizer calls first.
__attribute__((constructor)) static void register_cfjs(void) {
  if (!Py_IsInitialized()) PyImport_AppendInittab("_cfjs", init_cfjs);
}

// ---- dispatch ----

// What a call returns to JS, as a slot the shim takes: a JS value, or a
// rejected promise for a failure.
// The slot of a result: dispatch resolves to the value in it (bindgen.py),
// so the bridge doesn't lift it, and its none, ref.null, reaches JS as null.
static int32_t result_slot(PyObject *o) {
  if (o == Py_None) return tsgen_slot_dup(TSGEN_UNDEFINED);
  if (o == jsnull) return 0;
  if (PyObject_TypeCheck(o, &JsRefType)) {
    int32_t s = ref_slot((JsRef *)o);
    if (s < 0) return -1;
    return tsgen_slot_dup(s);
  }
  PyObject *keep = PyList_New(0);
  if (!keep) return -1;
  arg_t a;
  int32_t s = -1;
  if (arg_in(o, &a, keep, 0) == 0) s = tw_box(a.arm, a.s0, a.s1, a.s2, a.s3);
  Py_DECREF(keep);
  return s;
}

static int32_t failure_slot(PyObject *s) {
  Py_ssize_t n;
  const char *p = s ? PyUnicode_AsUTF8AndSize(s, &n) : NULL;
  if (!p) {
    PyErr_Clear();
    p = "Python error (unprintable)";
    n = (Py_ssize_t)strlen(p);
  }
  return tw_failure((int32_t)p, (int32_t)n);
}

// cfworkers.c
void cfworkers_start(void);
// pytask.c
int32_t cf_pytask_cx(void *lang);
extern int cfworkers_init_failed;

// Runs the dispatch hook for one call into the module, in context cx (a
// slot it takes), and returns the result's slot.
static int32_t run_dispatch(PyObject *cls, PyObject *method, int32_t self, int32_t ap, int32_t ab, int32_t an,
                            int32_t cx) {
  if (!Py_IsInitialized()) cfworkers_start();
  if (cfworkers_init_failed) {
    Py_XDECREF(cls);
    Py_XDECREF(method);
    if (self) tsgen_slot_free(self);
    tsgen_slot_free(cx);
    return tw_failure((int32_t) "Python failed to start; see the log.", 36);
  }
  int prev = tsgen_enter();
  cur_cx = cx;
  PyGILState_STATE gil = PyGILState_Ensure();
  int32_t out = 0;
  PyObject *pself = self ? new_ref_traits(self, -1) : Py_NewRef(Py_None);
  PyObject *argl = values_from(ap, ab, an), *r = NULL;
  if (cls && method && pself && argl) {
    if (!dispatch_hook) {
      PyErr_SetString(PyExc_RuntimeError, "Python failed to start; see the log.");
    } else {
      r = PyObject_CallFunctionObjArgs(dispatch_hook, cls, method, pself, argl, NULL);
    }
  }
  Py_XDECREF(cls);
  Py_XDECREF(method);
  Py_XDECREF(pself);
  Py_XDECREF(argl);
  if (r) {
    // The hook returns (True, value) or (False, message).
    PyObject *flag = PyTuple_Check(r) && PyTuple_GET_SIZE(r) == 2 ? PyTuple_GET_ITEM(r, 0) : NULL;
    if (!flag) {
      PyErr_SetString(PyExc_TypeError, "dispatch hook must return (ok, value)");
    } else if (flag == Py_True) {
      out = result_slot(PyTuple_GET_ITEM(r, 1));
      if (out < 0) out = 0;
      else goto done;
    } else {
      PyObject *s = PyObject_Str(PyTuple_GET_ITEM(r, 1));
      out = failure_slot(s);
      Py_XDECREF(s);
      goto done;
    }
  }
  {
    PyObject *exc = PyErr_GetRaisedException();
    PyObject *s = exc ? PyObject_Str(exc) : NULL;
    out = failure_slot(s);
    Py_XDECREF(s);
    Py_XDECREF(exc);
  }
done:
  Py_XDECREF(r);
  fflush(stdout);
  fflush(stderr);
  PyGILState_Release(gil);
  tsgen_slot_free(cx);
  tsgen_leave(prev);
  return out;
}

static PyObject *name_from(int32_t p, int32_t n) { return PyUnicode_DecodeUTF8((const char *)p, n, "strict"); }

__attribute__((export_name("cfts:dispatch(str,str,Any?,arr<Value>,Any?)")))
int32_t cf_dispatch(int32_t cp, int32_t cn, int32_t mp, int32_t mn, int32_t self, int32_t ap, int32_t ab, int32_t an,
                    int32_t cx) {
  // Before anything uses the shadow stack (this function has no frame).
  tsgen_note_entry();
  // A callback JS calls during a call runs in that call's context rather
  // than the one it was made in: the call that suspended last, which is
  // waiting for what JS is doing.
  if (tsgen_depth() > 0 && cn == 9 && !memcmp((const char *)cp, "$callback", 9)) {
    int32_t during = cf_pytask_cx(tsgen_last_suspended());
    if (during) {
      tsgen_slot_free(cx);
      cx = tsgen_slot_dup(during);
    }
  }
  return run_dispatch(name_from(cp, cn), name_from(mp, mn), self, ap, ab, an, cx);
}
